const MAX_RESULT_CHARS = 60000;
const MAX_WRITE_OPERATIONS = 100;
const IGNORED_DIRS = new Set(['.obsidian', '.claudian-plus', '.claudian', '.git', 'node_modules']);
const nativeBridgeUrl = typeof process !== 'undefined'
